// ===== 06-matcap-metal: the metal matcap for the mixer blades =====
// The owner's asset "3d assets/matcap/metall.png" (512×512), inlined as base64:
// the build must open offline as a SINGLE file, we have no external fetches.
// ⚠️⚠️ THE MODULE NUMBER < 20 IS DELIBERATE: the blades are built by TOP-LEVEL code in 20-arena,
// and a const from HIGHER-numbered modules is in the TDZ for it — exactly the pitfall that for six days
// kept losing the level (incident 2026-08-13). Functions hoist, constants do not.
// ⚠️ THE SIZE WAS NAMED TO THE OWNER: a 158 KB PNG -> ~212 KB of base64 in index.html.
// I did not squeeze it down to 256×256 — we take his assets as they are (a project rule);
// if the weight ever becomes an issue, that is one rebuild of the module.
const MATCAP_METAL_PNG = 'data:image/png;base64,';
let _metalMatcapTex = null;
// Loading uses the same trick as the palette atlases (36-models:modelColormap):
// a white 1×1 stub until decode, the source swapped in on onload. Without the stub
// the sampling returns zeros for the first frames, and the material flashes black.
function metalMatcapTex(){
  if (_metalMatcapTex) return _metalMatcapTex;
  const stub = document.createElement('canvas');
  stub.width = stub.height = 1;
  const g = stub.getContext('2d');
  g.fillStyle = '#fff'; g.fillRect(0, 0, 1, 1);
  const t = new THREE.Texture(stub);
  t.encoding = THREE.sRGBEncoding;
  t.magFilter = t.minFilter = THREE.LinearFilter;
  t.generateMipmaps = false;
  const img = new Image();
  img.onload = () => { t.image = img; t.needsUpdate = true; };
  img.src = MATCAP_METAL_PNG;
  _metalMatcapTex = t;
  return t;
}
